// Приймаємо push від Realting (якщо платформа вміє слати вебхуки) і зводимо до тієї ж схеми,
// що й у поллінговому воркфлоу.
const body = $json.body ?? $json;
const rows = Array.isArray(body) ? body : (body.data || body.items || body.orders || [body]);

const get = (obj, paths) => {
  for (const p of paths) {
    const v = p.split('.').reduce((a, c) => (a === null || a === undefined ? a : a[c]), obj);
    if (v !== undefined && v !== null && v !== '') return v;
  }
  return null;
};
const str = (v) => (v === null || v === undefined ? '' : String(v).trim());

return rows.map((r) => {
  const fullName = str(get(r, ['name', 'full_name', 'contact_name', 'client.name']));
  const parts = fullName.split(/\s+/).filter(Boolean);
  return {
    json: {
      externalId: str(get(r, ['id', 'order_id', 'uuid', 'number'])),
      name: parts[0] || fullName,
      lastName: parts.slice(1).join(' '),
      phone: str(get(r, ['phone', 'contact_phone', 'client.phone'])).replace(/[^\d+]/g, ''),
      email: str(get(r, ['email', 'contact_email', 'client.email'])).toLowerCase(),
      comment: str(get(r, ['message', 'comment', 'text'])),
      objectUrl: str(get(r, ['object_url', 'url', 'link'])),
      objectTitle: str(get(r, ['object_title', 'title'])),
      raw: r,
    },
  };
});

const out = [];
for (const item of $input.all()) {
  const l = item.json;
  const fields = {
    TITLE: 'Realting #' + (l.externalId || 'push') + (l.objectTitle ? ' — ' + l.objectTitle : ''),
    NAME: l.name || 'Без імені',
    LAST_NAME: l.lastName || '',
    SOURCE_ID: 'WEB',
    SOURCE_DESCRIPTION: 'realting.com (webhook)',
    COMMENTS: [l.comment, l.objectUrl, 'Realting ID: ' + l.externalId].filter(Boolean).join('\n'),
    ASSIGNED_BY_ID: Number($env.BITRIX_ASSIGNED_BY_ID || 1),
    UF_CRM_REALTING_ID: l.externalId,
    OPENED: 'Y',
    UTM_SOURCE: 'realting.com',
  };
  if (l.phone) fields.PHONE = [{ VALUE: l.phone, VALUE_TYPE: 'WORK' }];
  if (l.email) fields.EMAIL = [{ VALUE: l.email, VALUE_TYPE: 'WORK' }];
  out.push({ json: { payload: { fields, params: { REGISTER_SONET_EVENT: 'N' } } } });
}
return out;
